public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = Integer.parseInt(sc.next());

    List<Integer> q = new ArrayList<>();
    List<Integer> a = new ArrayList<>();
    List<Integer> b = new ArrayList<>();

    for (int i = 0; i < n; i++) {
        q.add(Integer.parseInt(sc.next()));
    }
    for (int i = 0; i < n; i++) {
        a.add(Integer.parseInt(sc.next()));
    }
    for (int i = 0; i < n; i++) {
        b.add(Integer.parseInt(sc.next()));
    }

    int max_servings_A = 0;
    int max_servings_B = 0;

    for (int i = 0; i < n; i++) {
        int max_A_i = a.get(i) > 0 ? q.get(i) / a.get(i) : 0;
        int remaining_q_i = q.get(i) - max_A_i * a.get(i);
        int max_B_i = b.get(i) > 0 ? remaining_q_i / b.get(i) : 0;

        max_servings_A += max_A_i;
        max_servings_B += max_B_i;
    }

    int answer = max_servings_A + max_servings_B;
    System.out.println(answer);
}
